package com.tuap.backend.auth; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import org.junit.jupiter.api.*; import org.mockito.*; import com.tuap.backend.config.EmailProperties;
class EmailChangeNotifierTest { @Test void sendsEncodedConfirmationToNewEmail(){EmailService email=mock(EmailService.class);EmailProperties p=new EmailProperties();p.setEmailChangeConfirmUrl("https://app.test/confirm-email-change");new EmailChangeNotifier(email,p).notifyChange("new@nextfit.test","a+b/c?=");ArgumentCaptor<String> html=ArgumentCaptor.forClass(String.class);verify(email).send(eq("new@nextfit.test"),eq("Confirma tu nuevo correo de NextFit"),html.capture());assertTrue(html.getValue().contains("token=a%2Bb%2Fc%3F%3D"));assertFalse(html.getValue().contains("password"));}}
